import cv2, glob, numpy as np
frames = sorted(glob.glob('/root/keyframes_*.png'))

def count_matches(img, tmpl, threshold=0.85, iou_thresh=0.3):
    res = cv2.matchTemplate(img, tmpl, cv2.TM_CCOEFF_NORMED)
    ys, xs = np.where(res >= threshold)
    if len(xs)==0:
        return 0
    w, h = tmpl.shape[::-1]
    boxes = [(x, y, x+w, y+h) for x,y in zip(xs, ys)]
    scores = [res[y, x] for x,y in zip(xs, ys)]
    order = np.argsort(scores)[::-1]
    selected = []
    for idx in order:
        x1,y1,x2,y2 = boxes[idx]
        keep=True
        for j in selected:
            xx1 = max(x1, boxes[j][0]); yy1=max(y1, boxes[j][1])
            xx2 = min(x2, boxes[j][2]); yy2=min(y2, boxes[j][3])
            inter = max(0, xx2-xx1) * max(0, yy2-yy1)
            area = (x2-x1)*(y2-y1)
            area_j = (boxes[j][2]-boxes[j][0])*(boxes[j][3]-boxes[j][1])
            iou = inter / float(area + area_j - inter + 1e-6)
            if iou > iou_thresh:
                keep=False
                break
        if keep:
            selected.append(idx)
    return len(selected)


templates = {name: cv2.imread(f'/root/{name}.png', cv2.IMREAD_GRAYSCALE) for name in ['coin','enemy','turtle']}

