import cv2, glob, numpy as np, csv, os

frames = sorted(glob.glob('/root/keyframes_*.png'))

# Convert frames to grayscale in-place
for fp in frames:
    img = cv2.imread(fp)
    if img is None:
        raise RuntimeError(f'Failed to read {fp}')
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    cv2.imwrite(fp, gray)

# Load grayscale templates
templates = {
    'coin': cv2.imread('/root/coin.png', cv2.IMREAD_GRAYSCALE),
    'enemy': cv2.imread('/root/enemy.png', cv2.IMREAD_GRAYSCALE),
    'turtle': cv2.imread('/root/turtle.png', cv2.IMREAD_GRAYSCALE),
}

for k,v in templates.items():
    if v is None:
        raise RuntimeError(f'Missing template {k}')

# Matching configuration
thresholds = {
    'coin': 0.78,
    'enemy': 0.85,
    'turtle': 0.80,
}


def count_matches(img, tmpl, threshold=0.8, iou_thresh=0.3):
    res = cv2.matchTemplate(img, tmpl, cv2.TM_CCOEFF_NORMED)
    ys, xs = np.where(res >= threshold)
    if len(xs) == 0:
        return 0
    w, h = tmpl.shape[::-1]
    boxes = [(x, y, x + w, y + h) for x, y in zip(xs, ys)]
    scores = [res[y, x] for x, y in zip(xs, ys)]
    order = np.argsort(scores)[::-1]
    selected = []
    for idx in order:
        x1, y1, x2, y2 = boxes[idx]
        keep = True
        for j in selected:
            xx1 = max(x1, boxes[j][0])
            yy1 = max(y1, boxes[j][1])
            xx2 = min(x2, boxes[j][2])
            yy2 = min(y2, boxes[j][3])
            inter = max(0, xx2 - xx1) * max(0, yy2 - yy1)
            area = (x2 - x1) * (y2 - y1)
            area_j = (boxes[j][2] - boxes[j][0]) * (boxes[j][3] - boxes[j][1])
            iou = inter / float(area + area_j - inter + 1e-6)
            if iou > iou_thresh:
                keep = False
                break
        if keep:
            selected.append(idx)
    return len(selected)

rows = []
for fp in frames:
    img = cv2.imread(fp, cv2.IMREAD_GRAYSCALE)
    if img is None:
        raise RuntimeError(f'Failed to read {fp} after grayscale conversion')
    counts = {}
    for name, tmpl in templates.items():
        counts[name] = count_matches(img, tmpl, threshold=thresholds[name])
    rows.append({
        'frame_id': fp,
        'coins': counts['coin'],
        'enemies': counts['enemy'],
        'turtles': counts['turtle'],
    })

with open('/root/counting_results.csv', 'w', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['frame_id','coins','enemies','turtles'])
    writer.writeheader()
    writer.writerows(rows)

print('wrote', '/root/counting_results.csv', 'rows', len(rows))
